ST.xhtml:p:
Rtring(CLK := g_biDDAxisHomeEnable OR bHomeEnable OR g_bDDAxisHomeEnable);

IF Rtring.Q THEN
  nHomingState :=1;
  g_boDDAxisHomeDone := FALSE;
  g_bDDAxisHomeDone := FALSE;
END_IF;

CASE nHomingState OF 
  0:
  nHomingState := 0;
  1:
  g_DDAxisHome.Execute := TRUE;
  g_DDAxisHome.Position := dHomePosition;
  g_DDAxisHome.bCalibrationCam := g_bDDAxisZero;
  g_DDAxisHome.DISTANCE := dHomeOffset;
  IF nHomingMode =0 THEN
    g_DDAxisHome.HomingMode := 0;
  ELSIF nHomingMode = 1 THEN
    g_DDAxisHome.HomingMode := 5;
  ELSIF nHomingMode = 3 THEN
       (*只是去掉回零标志位*)
    g_DDAxisHome.HomingMode := 1;
  END_IF;
  IF g_DDAxisHome.Done THEN
    g_DDAxishome.Execute := FALSE;
    g_boDDAxisHomeDone := TRUE;
    g_bDDAxisHomeDone := TRUE;
    nHomingState := 0;
  END_IF;
  IF g_bPlcPauseBuffer THEN
    nHomingState := 10;
  END_IF;
  IF g_DDAxisHome.CommandAborted OR g_DDAxisHome.error THEN
    nHomingState := 0;
    g_DDAxisHome.Execute := FALSE;
    g_boDDAxisHomeDone := FALSE;
  END_IF;
  10:
  g_DDAxisHome.Execute := FALSE;
  g_DDAxisStop.Execute := TRUE;
  IF g_DDAxisStop.Done AND g_bPlcStartBuffer THEN
    g_DDAxisStop.Execute := FALSE;
    nHomingState := 1;
  END_IF;
  IF g_DDAxisStop.CommandAborted OR g_DDAxisStop.error THEN
    g_DDAxisStop.Execute := FALSE;
    nHomingState :=0;
  END_IF;
END_CASE;

IF bChangeHomeMode THEN
  bChangeHomeMode := FALSE;
  nChangeHomeModeState := 1;
END_IF;
(*置零点功能*)
CASE nChangeHomeModeState OF
  0:
    nChangeHomeModeState := 0;
  1:
    g_DDAxisHome.Execute := TRUE;
    IF nHomingMode = 0 THEN
      g_DDAxisHome.HomingMode := 0;
    ELSIF nHomingMode = 1 THEN
      g_DDAxisHome.HomingMode := 5;
    ELSIF nHomingMode = 2 THEN
      g_DDAxisHome.HomingMode := 4;
    END_IF;
  g_DDAxisHome.Position := 0.0;
  g_DDAxisHome.DISTANCE := 0.0;
    IF g_DDAxisHome.Done THEN
      g_DDAxisHome.Execute := FALSE;
      nChangeHomeModeState := 0;
    END_IF;
    IF g_DDAxisHome.CommandAborted OR g_DDAxisHome.Error THEN
      g_DDAxisHome.Execute := FALSE;
      nChangeHomeModeState := 0;
    END_IF;
END_CASE;

(***界面上下发了去掉T3轴回零标志***)
IF g_bCleanT3Homed THEN
   g_DDAxisHome.HomingMode := 1;
   g_DDAxisHome.Execute := TRUE; 
   g_bDDAxisHomeDone := FALSE; 
   IF g_DDAxisHome.DONE OR g_DDAxisHome.ERROR THEN 
    g_DDAxisHome.Execute := FALSE; 
    g_bCleanT3Homed := FALSE; 
   END_IF;
END_IF;
(*伺服断电恢复基准点*)
Rtring_T3Recover(CLK := g_bRecoverT3DatumMark);
IF Rtring_T3Recover.Q THEN
  g_bRecoverT3DatumMark := FALSE;
  nRecoverT3DatumMarkState := 1;
END_IF;
CASE nRecoverT3DatumMarkState OF
  1:
   g_DDAxisHome.HomingMode := 4;
   g_DDAxisHome.Position :=g_dT3DatumMark; (*恢复基准点坐标差值*)
   g_DDAxisHome.Execute := TRUE;  
   IF  g_DDAxisHome.DONE OR g_DDAxisHome.ERROR THEN 
		g_boDDAxisHomeDone := TRUE;
		g_bDDAxisHomeDone := TRUE;
		g_DDAxisHome.Execute := FALSE; 
		nRecoverT3DatumMarkState := 0; 
   END_IF;
END_CASE;
IF g_bPlcResetBuffer THEN
  g_DDAxisHome.Execute := FALSE;
  nHomingState :=0;
  g_DDAxisRel.Execute := FALSE;
  g_DDAxisStop.Execute := FALSE;
  g_bDDAxisHomeDone := TRUE;
  g_bRecoverT3DatumMark := FALSE;
END_IF; 

g_nT3HomeMode := nHomingMode;
